		"blob":         blob,
		"content_hash": key,
	}
	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return "", err
	}
	data = append(data, '\n')
	if err := writeFileAtomic(filepath.Join(generationDir, rel), data, 0o600); err != nil {
		return "", err
	}
	return filepath.ToSlash(rel), nil
}

