+FROM symbols s
+JOIN symbol_fts f ON f.id = s.id
+WHERE lower(f.text) LIKE ?
+ORDER BY CASE WHEN lower(s.name) = lower(?) THEN 0 WHEN lower(s.qualified_name) = lower(?) THEN 1 ELSE 2 END, s.qualified_name
