   568		if err := rejectExistingSymlinkPathComponents(brainDir, filepath.Join(semanticDirName, semanticGenerationsDir)); err != nil {
   569			return "", semanticBuildMetrics{}, err
   570		}
   571		if err := os.MkdirAll(generationsRoot, 0o700); err != nil {
   572			return "", semanticBuildMetrics{}, fmt.Errorf("create semantic generations dir: %w", err)
   573		}
   574		tmpDir, err := os.MkdirTemp(generationsRoot, ".tmp-"+generationID+"-*")
   575		if err != nil {
   576			return "", semanticBuildMetrics{}, err
   577		}
   578		cleanup := true
   579		defer func() {
   580			if cleanup {
   581				_ = os.RemoveAll(tmpDir)
   582			}
   583		}()
   584	
   585		dbPath := filepath.Join(tmpDir, semanticSQLiteName)
   586		db, err := sql.Open("sqlite", dbPath)
   587		if err != nil {
   588			return "", semanticBuildMetrics{}, err
   589		}
   590		if err := initializeSemanticSQLite(db); err != nil {
   591			_ = db.Close()
   592			return "", semanticBuildMetrics{}, err
   593		}
   594		metrics, err := populateSemanticSQLite(db, repoDir, generationID, raw, header, counts, now, tmpDir)
   595		if closeErr := db.Close(); err == nil && closeErr != nil {
   596			err = closeErr
   597		}
   598		if err != nil {
   599			return "", semanticBuildMetrics{}, err
   600		}
   601		info, err := os.Stat(dbPath)
   602		if err != nil {
   603			return "", semanticBuildMetrics{}, err
   604		}
   605		metrics.StoreBytes = info.Size()
   606		metrics.BuildMillis = time.Since(start).Milliseconds()
   607		metricsData, err := json.MarshalIndent(metrics, "", "  ")
   608		if err != nil {
   609			return "", semanticBuildMetrics{}, err
   610		}
   611		metricsData = append(metricsData, '\n')
   612		if err := writeFileAtomic(filepath.Join(tmpDir, semanticMetricsName), metricsData, 0o600); err != nil {
   613			return "", semanticBuildMetrics{}, err
   614		}
   615	
   616		finalDir := filepath.Join(generationsRoot, generationID)
   617		if err := rejectExistingSymlinkPathComponents(brainDir, filepath.Join(semanticDirName, semanticGenerationsDir, generationID)); err != nil {
   618			return "", semanticBuildMetrics{}, err
   619		}
   620		if err := os.RemoveAll(finalDir); err != nil {
   621			return "", semanticBuildMetrics{}, err
   622		}
   623		if err := os.Rename(tmpDir, finalDir); err != nil {
   624			return "", semanticBuildMetrics{}, err
   625		}
   626		cleanup = false
   627		return filepath.ToSlash(filepath.Join(semanticDirName, semanticGenerationsDir, generationID)), metrics, nil
   628	}
